var QUESTOES_HIFEN = [{"id":1370,"enunciado":"No que diz respeito às regras do novo acordo ortográfico, analise as afirmativas abaixo: I.Os vocábulos 'paraquedas', 'parabrisa' e 'mandachuva' continuarão a ser grafados sem hífen. II.Os vocábulos 'bem-vindo', 'recém-casado' e 'bem-querer' estão hifenizados corretamente. III.Serão hifenizados os adjetivos gentílicos derivados de nomes geográficos compostos que contenham ou não elemento de ligação como 'belo-horizontino' e 'mato-grossense-do-sul'. IV.O acento circunflexo não é mais empregado em palavras paroxítonas que terminam em 'êem' e em 'ôo' como 'veem' e 'abençoo'. V.São acentuadas as vogais tônicas 'i' e 'u' das palavras paroxítonas quando estas vogais estiverem precedidas de ditongo decrescente como 'feiúra' e 'bocaiúva.' VI. Estão grafados corretamente sem hífen os vocábulos: afrodescendente, eurocêntrico. VII.'Anti-inflamatório', 'micro-ondas' e 'eletro-ótica' são hifenizadas, pois nas formações com prefixos, emprega-se o hífen quando o 1º elemento termina por vogal igual à que inicia o 2º elemento. Estão corretas:","opcoes":["Apenas I, II, IV e VI.","Apenas I, II, V e VII.","Apenas II, III, IV, VI e VII.","Apenas II, IV e VII."],"correta":2,"explicacao":"Gabarito: <strong>Apenas II, III, IV, VI e VII.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["hifen","ditongos","paroxitonas","ortografia"]},{"id":2607,"enunciado":"Analise as assertivas que seguem acerca do fragmento do Texto I: “A outra é o banco de dados do Open Payments, um programa nacional que exige que empresas produtoras de medicamentos e dispositivos médicos informem “valores transferidos” a médicos, enfermeiros-chefes e hospitais” (4 º parágrafo). I- O trecho que inicia em “um programa nacional” exerce função de aposto explicativo, pois acrescenta uma informação sobre “Open Payments”. II- O uso do hífen em “enfermeiros-chefes” está inadequado, pois, nesse caso, a forma correta seria sem hífen. III- O segmento “um programa nacional que exige que empresas \\[...]” apresenta uma restrição ao sentido de “Open Payments”. IV- As aspas em “valores transferidos” foram empregadas para dar ênfase à expressão e, no contexto apresentado, poderiam ser substituídas por vírgulas. É CORRETO o que se afirma em:","opcoes":["I, II, III e IV","I, apenas.","I e IV, apenas.","IV, apenas.","II e III, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, apenas.</strong>.","banca":"CPCON","ano":2026,"temas_relacionados":["hifen"]},{"id":2816,"enunciado":"\"A própria comunidade, que é capacitada com formação de mão de obra, passa a ser protagonista da preservação de seus lugares\". Com base na ortografia da palavra 'mão de obra', analise as afirmativas a seguir e assinale a correta.","opcoes":["A grafia 'mão de obra', sem hífen, está em conformidade com o Novo Acordo Ortográfico, segundo o qual, em regra, as locuções deixam de ser grafadas com hífen, como ocorre em 'café com leite' e 'fim de semana'. Entretanto, o vocábulo 'andorinha-do-mar' mantém corretamente o hífen por se tratar de uma composição vocabular regida por regra específica distinta.","A expressão 'mão de obra' deveria ser grafada com hífen, 'mão-de-obra', pois se trata de substantivo composto formado por elementos que, individualmente, já possuem sentido próprio, critério que, pelo Acordo Ortográfico vigente, determina obrigatoriamente o uso do hífen em compostos cujos elementos conservam sua autonomia semântica, assim como ocorre com 'ervilha-de-cheiro'.","A expressão 'mão de obra' é grafada sem hífen por ser classificada como locução adjetiva, uma vez que exerce a função de modificador do substantivo 'formação' no trecho, indicando o tipo de capacitação oferecida à comunidade, o que a aproxima gramaticalmente de locuções adjetivas como 'de qualidade' e 'de excelência'.","O vocábulo 'mão de obra', sem hífen, está em conformidade com o Novo Acordo Ortográfico, segundo o qual as locuções unidas por preposição deixam de ser grafadas com hífen, como ocorre em 'cor de rosa' e 'água de colônia', permanecendo o hífen apenas nos compostos formados por justaposição sem elemento de ligação, como 'guarda-chuva' e 'terça-feira'."],"correta":0,"explicacao":"Gabarito: <strong>A grafia 'mão de obra', sem hífen, está em conformidade com o Novo Acordo Ortográfico, segundo o qual, em regra, as locuções deixam de ser grafadas com hífen, como ocorre em 'café com leite' e 'fim de semana'. Entretanto, o vocábulo 'andorinha-do-mar' mantém corretamente o hífen por se tratar de uma composição vocabular regida por regra específica distinta.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["hifen","ortografia"]},{"id":2818,"enunciado":"De acordo com as normas de ortografia, qual das palavras a seguir é grafada com hífen, considerando a mesma regra utilizada em “anti-inflamatória” (7º§)?","opcoes":["Micro-ondas.","Pré-operatório.","Mal-intencionado.","Ensino-aprendizagem."],"correta":0,"explicacao":"Gabarito: <strong>Micro-ondas.</strong>.","banca":"Instituto Consulplan","ano":2026,"temas_relacionados":["hifen","ortografia"]},{"id":2823,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item seguinte.\nConforme o Acordo Ortográfico da Língua Portuguesa, as palavras “antiobesidade” e “cardiovasculares”, presentes no texto, estão corretamente grafadas, entretanto “multiprofissional” deveria ser grafada com hífen, por ser formada pelo prefixo “multi‑”, que é seguido de uma palavra iniciada por consoante.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["hifen","ortografia"]},{"id":2827,"enunciado":"Tratando-se do uso, ou não, do emprego do hífen, marque a alternativa indevida.","opcoes":["Não se aplica o hífen nas ligações verbais, formadoras de locuções verbais, com o verbo “haver” + preposição “de”.","Utiliza-se o hífen em vocábulos compostos, formados por “substantivo + substantivo”, nos quais o segundo substantivo indique forma, finalidade ou tipo.","Usa-se o hífen para indicar a ênclise dos pronomes oblíquos átonos às formas verbais.","Emprega-se o hífen nos vocábulos derivados por prefixação, cujo prefixo terminar em vogal e o segundo elemento iniciar-se por consoante. Caso o segundo elemento inicie por “r” ou “s”, estas consoantes não devem ser duplicadas."],"correta":3,"explicacao":"Gabarito: <strong>Emprega-se o hífen nos vocábulos derivados por prefixação, cujo prefixo terminar em vogal e o segundo elemento iniciar-se por consoante. Caso o segundo elemento inicie por “r” ou “s”, estas consoantes não devem ser duplicadas.</strong>.","banca":"MSConcursos","ano":2026,"temas_relacionados":["hifen"]},{"id":2829,"enunciado":"A palavra “contra-arrazoado” está hifenizada devidamente, o que não ocorre na escrita do vocábulo:","opcoes":["Sub-braquial.","Recém-casado.","Decreto-lei.","Infra-som."],"correta":3,"explicacao":"Gabarito: <strong>Infra-som.</strong>.","banca":"MSConcursos","ano":2026,"temas_relacionados":["hifen"]},{"id":2831,"enunciado":"\"Nos últimos quatro meses, os quatro maiores bancos norte-americanos demitiram 15 mil funcionários, enquanto obtinham mais de US$ 1 bilhão de lucro.\" O vocábulo 'norte-americano' é grafado com hífen em conformidade com regra específica. Com base nas demais regras de emprego do hífen, preencha as lacunas com palavras corretamente grafadas, com ou sem hífen. I.O pesquisador descreveu o personagem como um líder\\_\\_\\_ , marcado por sucessivas derrotas políticas. II.O movimento\\_\\_\\_ busca valorizar identidades culturais e históricas do continente em contextos contemporâneos. III.A\\_\\_\\_ foi um marco histórico que ampliou o conhecimento geográfico e as rotas comerciais. IV.O\\_\\_\\_ participou ativamente do programa, enviando perguntas ao vivo durante a transmissão. Assinale a alternativa que apresenta as palavras que preenchem, correta e respectivamente, as lacunas propostas.","opcoes":["mal-afortunado, neoafricano, circunavegação, rádio-ouvinte","mal-afortunado, neoafricano, circum-navegação, radiouvinte","malafortunado, neoafricano, circum-navegação, rádio-ouvinte.","mal-afortunado, neo-africano, circunavegação, rádio-ouvinte"],"correta":1,"explicacao":"Gabarito: <strong>mal-afortunado, neoafricano, circum-navegação, radiouvinte</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["hifen"]},{"id":2835,"enunciado":"Com base nas regras do Acordo Ortográfico vigente, analise as afirmativas a seguir e julgueas como verdadeiras (V) ou falsas (F). ( ) A grafia correta é \"multissemiótico\", com \"ss\", pois o prefixo multi- termina em vogal e a base \"semiótico\" começa com \"s\", exigindo duplicação da consoante. ( ) A forma correta é \"inter-relação\", com hífen, pois o prefixo inter- termina em \"r\" e a base começa com \"r\", caso em que o Acordo Ortográfico determina o uso do hífen. ( ) A palavra \"autorreferente\" deve ser escrita sem hífen e com \"rr\", pois o prefixo auto- termina em vogal e a base começa com \"r\", resultando em duplicação da consoante sem hífen. ( ) A forma “presuposição” está grafada corretamente segundo a norma-padrão. Após análise, conclui-se que a sequência correta é:","opcoes":["V – V – F – F.","V – V – V – F.","F – V – V – F.","V – F – F – V.","F – F – V – V."],"correta":1,"explicacao":"Gabarito: <strong>V – V – V – F.</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["hifen","ortografia"]},{"id":2836,"enunciado":"\"Encontrar objetos em ambientes do nosso dia a dia depende de um processo chamado busca visual, e nosso cérebro não é tão eficiente nisso.\" O emprego do hífen em locuções, como 'dia a dia', foi, na maioria dos casos, abolido. No entanto, há exceções à regra, e algumas expressões devem ser grafadas com hífen. Com base nisso, complete as lacunas a seguir com a forma correta dessas expressões. Acordou tarde, sem alarme, sem rotina, sem plano. O \\_\\_\\_\\_\\_\\_\\_\\_\\_ foi improvisado — pão dormido e uma fatia de queijo que já estava pedindo aposentadoria. Comeu de pé, encostado na pia, olhando pela janela o céu que amanhecera \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_, daquele rosa suave de quem não sabe bem se ainda é noite ou já é dia. O \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ latiu uma vez, duas, depois se calou — talvez tivesse percebido que o dono também estava sem disposição para vigilância. Naquele domingo, decidiu que viveria \\_\\_\\_\\_\\_\\_\\_\\_\\_. Sem compromisso, sem lista, sem culpa.","opcoes":["café com leite, cor-de-rosa, cão de guarda, ao deus-dará.","café-com-leite, cor de rosa, cão-de-guarda, ao deus-dará.","café com leite, cor de rosa, cão-de-guarda, ao deus dará.","café-com-leite, cor-de-rosa, cão de guarda, ao deus-dará."],"correta":0,"explicacao":"Gabarito: <strong>café com leite, cor-de-rosa, cão de guarda, ao deus-dará.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["hifen"]},{"id":2839,"enunciado":"\"Microfones especiais podem nos ajudar a detectar ruídos inaudíveis para o ouvido humano, como os sons ultrassônicos emitidos pelos morcegos.\" Com base nas regras de emprego do hífen em palavras compostas, assinale a alternativa que apresenta a justificativa correta para o vocábulo 'ultrassônico'.","opcoes":["O vocábulo 'ultrassônico' não recebe hífen, pois, nos casos em que se perdeu a noção de composição, a palavra deve ser escrita sem esse sinal, como ocorre também em 'madressilva' e 'paraquedas'.","O vocábulo 'ultrassônico' não recebe hífen, pois o primeiro elemento termina em vogal e o segundo começa por 's', havendo a duplicação dessa consoante, em processo semelhante ao que ocorre em 'cosseno'.","O vocábulo 'ultrassônico' não recebe hífen, pois, após o Novo Acordo Ortográfico, formações com esse prefixo não são mais hifenizadas, ocorrendo a duplicação da consoante inicial do segundo elemento, como também se verifica em 'ultrassom'.","O vocábulo 'ultrassônico' está grafado incorretamente, uma vez que palavras que guardam sua independência fonética devem ser escritas com hífen, como em 'ultra-sônico', a exemplo de 'sobre-humano' e 'proto-história'."],"correta":1,"explicacao":"Gabarito: <strong>O vocábulo 'ultrassônico' não recebe hífen, pois o primeiro elemento termina em vogal e o segundo começa por 's', havendo a duplicação dessa consoante, em processo semelhante ao que ocorre em 'cosseno'.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["hifen"]},{"id":2845,"enunciado":"\"Microfones especiais podem nos ajudar a detectar ruídos inaudíveis para o ouvido humano, como os sons ultrassônicos emitidos pelos morcegos.\" Com base nas regras de emprego do hífen em palavras compostas, assinale a alternativa que apresenta a justificativa correta para o vocábulo 'ultrassônico'.","opcoes":["O vocábulo 'ultrassônico' não recebe hífen, pois, após o Novo Acordo Ortográfico, formações com esse prefixo não são mais hifenizadas, ocorrendo a duplicação da consoante inicial do segundo elemento, como também se verifica em 'ultrassom'.","O vocábulo 'ultrassônico' não recebe hífen, pois, nos casos em que se perdeu a noção de composição, a palavra deve ser escrita sem esse sinal, como ocorre também em 'madressilva' e 'paraquedas'.","O vocábulo 'ultrassônico' está grafado incorretamente, uma vez que palavras que guardam sua independência fonética devem ser escritas com hífen, como em 'ultra-sônico', a exemplo de 'sobre-humano' e 'proto-história'.","&#x20;O vocábulo 'ultrassônico' não recebe hífen, pois o primeiro elemento termina em vogal e o segundo começa por 's', havendo a duplicação dessa consoante, em processo semelhante ao que ocorre em 'cosseno'."],"correta":3,"explicacao":"Gabarito: <strong>&#x20;O vocábulo 'ultrassônico' não recebe hífen, pois o primeiro elemento termina em vogal e o segundo começa por 's', havendo a duplicação dessa consoante, em processo semelhante ao que ocorre em 'cosseno'.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["hifen"]},{"id":2860,"enunciado":"Assinale a alternativa em que, como \"puxa-saco\" (linha 19), a palavra está escrita conforme as normas oficiais vigentes.","opcoes":["anti-ético.","re-edição.","auto-regulação.","super-realístico."],"correta":3,"explicacao":"Gabarito: <strong>super-realístico.</strong>.","banca":"FCPC","ano":2026,"temas_relacionados":["hifen"]},{"id":2893,"enunciado":"\"O ministro da Saúde participou nesta quinta-feira (4) da reunião de início da implantação do Instituto Tecnológico de Medicina Inteligente (ITMI-Brasil).\" Com base nas regras do emprego do hífen, como 'quinta-feira', assinale a alternativa que apresenta vocábulos grafados corretamente com ou sem hífen.","opcoes":["sub-rogar; bem-feitor; afro-luso-brasileiro.","pé-de-meia; cor de café com leite; sota-almirante.","para-quedas; pré-natal; ultraelevado.","pré-requisito; semirrígido; mini-saia."],"correta":1,"explicacao":"Gabarito: <strong>pé-de-meia; cor de café com leite; sota-almirante.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["hifen"]},{"id":2894,"enunciado":"A palavra “sobre-estimar” está hifenizada devidamente, o que não ocorre na escrita do vocábulo:","opcoes":["Capim-açu.","Bem-querer.","Hiper-realista.","Co-educação."],"correta":3,"explicacao":"Gabarito: <strong>Co-educação.</strong>.","banca":"MSConcursos","ano":2026,"temas_relacionados":["hifen"]},{"id":2896,"enunciado":"Reportando-se ao uso, ou não do hífen, marque a alternativa incorreta.","opcoes":["Vice-cônsul.","Comum-de-dois.","Vizo-rei.","Sota-vento."],"correta":1,"explicacao":"Gabarito: <strong>Comum-de-dois.</strong>.","banca":"MSConcursos","ano":2026,"temas_relacionados":["hifen"]},{"id":2897,"enunciado":"Reportando-se ao uso, ou não do hífen, marque a alternativa incorreta.","opcoes":["&#x20;Pós-graduação.","&#x20;Dia-a-dia.","Sota-capitão.","Ex-presidente"],"correta":1,"explicacao":"Gabarito: <strong>&#x20;Dia-a-dia.</strong>.","banca":"MSConcursos","ano":2026,"temas_relacionados":["hifen"]},{"id":2898,"enunciado":"\"Mas qual a relação entre o Ophiocordyceps e o Purpureocillium atlanticum recém-descoberto?\" O uso do hífen nos compostos sem elemento de ligação, quando o primeiro elemento é a forma 'recém', ocorre de modo semelhante ao emprego do hífen com outros prefixos apresentados a seguir, EXCETO:","opcoes":["O cientista respondeu às perguntas sem-cerimônia, explicando os dados de forma direta e objetiva.","O pesquisador manteve um tom bem-humorado durante toda a entrevista, apesar da complexidade do tema.","O co-piloto auxiliou na navegação durante o deslocamento da equipe até a área da expedição.","A descoberta teve repercussão além-mar, sendo comentada por instituições científicas estrangeiras."],"correta":2,"explicacao":"Gabarito: <strong>O co-piloto auxiliou na navegação durante o deslocamento da equipe até a área da expedição.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["hifen"]},{"id":2899,"enunciado":"\"Ele identificou 123 'polimorfismos de risco', que são pequenas diferenças no código do DNA humano, associadas à enxaqueca.\" O vocábulo 'polimorfismos' não apresenta hífen. Nas frases abaixo, todas as palavras compostas estão corretamente grafadas sem hífen, exceto:","opcoes":["Ela comprou uma minissaia vermelha para o baile da escola.","O médico pediu para colocar o remédio no frasco com contagotas.","O professor organiza atividades extraescolares para os alunos todos os sábados.","O soldado saltou do avião usando seu paraquedas de segurança."],"correta":1,"explicacao":"Gabarito: <strong>O médico pediu para colocar o remédio no frasco com contagotas.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["hifen"]},{"id":2902,"enunciado":"\"Outra mudança administrativa prevista é a autorização para realização de exames médico-periciais por telemedicina ou análise documental, medida que pode simplificar procedimentos de avaliação médica de servidores públicos. O vocábulo 'telemedicina' está grafado corretamente sem hífen, assim como aqueles apresentados nas alternativas a seguir, exceto:","opcoes":["Contraordem e supraestrutura.","Benquerer e malcriado.","Ultrassom e mandachuva.","Autoescola e paralama."],"correta":3,"explicacao":"Gabarito: <strong>Autoescola e paralama.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["hifen"]},{"id":2904,"enunciado":"\"À época, William Pitt, primeiro-ministro da Grã-Bretanha, viu na tributação geral uma oportunidade de financiar os conflitos entre o país e Napoleão Bonaparte, líder francês.\" Com base nas regras de emprego do hífen em palavras compostas, analise as afirmativas a seguir: I.O vocábulo 'primeiro-ministro' está hifenizado corretamente, pois emprega-se o hífen nos compostos quando o primeiro termo está representado por forma numeral. II.O vocábulo 'Grã-Bretanha' está hifenizado corretamente, assim como 'Baía de Todos-os-Santos', 'Trás-os-Montes' e 'Entre-os-Rios', pois todos representam formas geográficas. III.Assim como o vocábulo 'primeiro-ministro', o emprego do hífen também está correto em 'beija-flor', 'guarda-noturno' e 'manda-chuva'. IV.As locuções substantivas, adjetivas e adverbiais não recebem hífen, como em 'cão de guarda', 'cor de vinho' e 'depois de amanhã'. No entanto, 'cor-de-rosa' é grafado com hífen por se tratar de um composto consagrado pelo uso. Assinale a alternativa que apresenta as proposições corretas:","opcoes":["I, II, III e IV.","II e III, apenas","I, III e IV, apenas.","I, II e IV, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["hifen"]},{"id":2905,"enunciado":"&#x20;\"A corrida para a recuperação de passageiros encontra diversos desafios, como mudanças nos hábitos pós-crise sanitária...\". O emprego do hífen em palavras compostas com o prefixo 'pós', como em 'pós-crise', assim como nos prefixos 'pre', 'pro' e 'co', depende de alguns critérios específicos de hifenização. Com base nisso, complete as lacunas a seguir com palavras grafadas corretamente. \"O estudo científico exige rigor ao\\_\\_\\_\\_\\_\\_critérios de análise, garantindo que os resultados sejam confiáveis e comparáveis. Nesse contexto, pesquisadores de diferentes instituições podem\\_\\_\\_\\_\\_\\_entre si para ampliar o alcance das descobertas e compartilhar conhecimentos. Em pesquisas da área da biologia, por exemplo, investiga-se o desenvolvimento do\\_\\_\\_\\_\\_\\_, etapa inicial do processo embrionário que ajuda a compreender a formação dos seres vivos.\" Assinale a alternativa que preenche corretamente as lacunas.","opcoes":["pré-estabelecer, co-operar e proembrião.","pré-estabelecer, cooperar e proembrião.","pré-estabelecer, co-operar e pró-embrião.","preestabelecer, cooperar e proembrião."],"correta":3,"explicacao":"Gabarito: <strong>preestabelecer, cooperar e proembrião.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["hifen"]},{"id":2925,"enunciado":"\"Existem expressões às quais nos acostumamos tanto que não nos surpreendem mais. Mas, se repensarmos um pouco, elas podem despertar nossa curiosidade.De vez em quando, por exemplo, ficamos sabendo que os cientistas detectaram um astro até então desconhecido, que fica a bilhões de anos-luz de distância.\" O emprego do hífen em palavras compostas, como em 'anos-luz', segue regras específicas de hifenização. Com base nisso, marque com V as afirmativas verdadeiras ou com F as falsas. (\\_\\_)Quando o primeiro elemento da palavra composta está representado por forma substantiva, adjetiva, numeral ou verbal, ocorre hífen, como em couve-flor, azul-escuro, primeiro-ministro e para-quedas. (\\_\\_)Quando o primeiro elemento está representado pela forma 'mal' e o 2º elemento começa por 'vogal', 'h' ou 'l', emprega-se o hífen, como em mal-informado, 'mal-humorado' e 'mal-limpo'. Por outro lado, 'malcriado' não recebe hífen, pois não se enquadra nessas regras. (\\_\\_)Normalmente as locuções não são hifenizadas, como 'mão de obra', 'dia a dia', Bumba meu boi. No entanto, são exceções à regra os vocábulos 'cor-de-rosa' e 'arco-da-velha', que são hifenizados. (\\_\\_)Os vocábulos 'ultrassom' e 'maxirresultado', que antes eram grafados com hífen, passaram a ser escritos sem esse sinal, com duplicação das consoantes 's' e 'r'. Após análise, assinale a alternativa que apresenta a sequência CORRETA.","opcoes":["F, V, V, F.","V, F, F, V.","&#x20;V, V, F, V.","&#x20;F, V, V, V.","V, V, V, V"],"correta":3,"explicacao":"Gabarito: <strong>&#x20;F, V, V, V.</strong>.","banca":"Unesc","ano":2026,"temas_relacionados":["hifen"]},{"id":2926,"enunciado":"\"Existem expressões às quais nos acostumamos tanto que não nos surpreendem mais. Mas, se repensarmos um pouco, elas podem despertar nossa curiosidade.De vez em quando, por exemplo, ficamos sabendo que os cientistas detectaram um astro até então desconhecido,  que fica a bilhões de anos-luz de distância.\" O emprego do hífen em palavras compostas, como em 'anos-luz', segue regras específicas de hifenização. Com base nisso, marque com V as afirmativas verdadeiras ou com F as falsas. (\\_\\_)Quando o primeiro elemento da palavra composta está representado por forma substantiva, adjetiva, numeral ou verbal, ocorre hífen, como em couve-flor, azul-escuro, primeiro-ministro e para-quedas. (\\_\\_)Quando o primeiro elemento está representado pela forma 'mal' e o 2º elemento começa por 'vogal', 'h' ou 'l', emprega-se o hífen, como em mal-informado, 'mal-humorado' e 'mal-limpo'. Por outro lado, 'malcriado' não recebe hífen, pois não se enquadra nessas regras. (\\_\\_)Normalmente as locuções não são hifenizadas, como 'mão de obra', 'dia a dia', Bumba meu boi. No entanto, são exceções à regra os vocábulos 'cor-de-rosa' e 'arco-da-velha', que são hifenizados. (\\_\\_)Os vocábulos 'ultrassom' e 'maxirresultado', que antes eram grafados com hífen, passaram a ser escritos sem esse sinal, com duplicação das consoantes 's' e 'r'. Após análise, assinale a alternativa que apresenta a sequência CORRETA.","opcoes":["&#x20;V, V, F, V","F, V, V, V.","&#x20;V, V, V, V.","V, F, F, V.","&#x20;F, V, V, F."],"correta":1,"explicacao":"Gabarito: <strong>F, V, V, V.</strong>.","banca":"Unesc","ano":2026,"temas_relacionados":["hifen"]},{"id":2927,"enunciado":"\"Existem expressões às quais nos acostumamos tanto que não nos surpreendem mais. Mas, se repensarmos um pouco, elas podem despertar nossa curiosidade.De vez em quando, por exemplo, ficamos sabendo que os cientistas detectaram um astro até então desconhecido, que fica a bilhões de anos-luz de distância.\" O emprego do hífen em palavras compostas, como em 'anos-luz', segue regras específicas de hifenização. Com base nisso, marque com V as afirmativas verdadeiras ou com F as falsas. (\\_\\_)Quando o primeiro elemento da palavra composta está representado por forma substantiva, adjetiva, numeral ou verbal, ocorre hífen, como em couve-flor, azul-escuro, primeiro-ministro e para-quedas. (\\_\\_)Quando o primeiro elemento está representado pela forma 'mal' e o 2º elemento começa por 'vogal', 'h' ou 'l', emprega-se o hífen, como em mal-informado, 'mal-humorado' e 'mal-limpo'. Por outro lado, 'malcriado' não recebe hífen, pois não se enquadra nessas regras. (\\_\\_)Normalmente as locuções não são hifenizadas, como 'mão de obra', 'dia a dia', Bumba meu boi. No entanto, são exceções à regra os vocábulos 'cor-de-rosa' e 'arco-da-velha', que são hifenizados. (\\_\\_)Os vocábulos 'ultrassom' e 'maxirresultado', que antes eram grafados com hífen, passaram a ser escritos sem esse sinal, com duplicação das consoantes 's' e 'r'. Após análise, assinale a alternativa que apresenta a sequência CORRETA.","opcoes":["F, V, V, V.","&#x20;F, V, V, F.","&#x20;V, V, F, V.","V, F, F, V","V, V, V, V"],"correta":0,"explicacao":"Gabarito: <strong>F, V, V, V.</strong>.","banca":"Unesc","ano":2026,"temas_relacionados":["hifen"]},{"id":2928,"enunciado":"\"Produção agrícola maior deve fortalecer geração de bioenergia.\" O vocábulo 'bioenergia' apresenta-se corretamente grafado sem hífen. Considerando o uso ou não do hífen em palavras compostas, identifique a alternativa que apresenta pelo menos um vocábulo grafado de forma INCORRETA.","opcoes":["O guia turístico, sempre bem-humorado e benquisto, conduzia o grupo com histórias engraçadas sobre a cidade.","Os fones supra-auriculares foram distribuídos aos participantes, seguindo os horários preestabelecidos pelo organizador do evento.","Após o fim de semana, ele apareceu com cara de mamão-macho após saber do resultado da reunião.","Para acompanhar o ritmo circumeridiano dos astronautas, a equipe precisou de um esforço quase sobre-humano na organização das tarefas.","Os viajantes exploraram a Baía de Todos-os-Santos sem roteiro definido, confiando ao deus-dará que tudo daria certo durante a viagem."],"correta":3,"explicacao":"Gabarito: <strong>Para acompanhar o ritmo circumeridiano dos astronautas, a equipe precisou de um esforço quase sobre-humano na organização das tarefas.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["hifen"]},{"id":2930,"enunciado":"\"Aluno e professora criam tecido com bagaço da cana-de-açúcar, em Goiás.\" Considerando o uso do hífen no vocábulo 'cana-de-açúcar', bem como sua adequada justificativa e a aplicação desse recurso em outras palavras alheias ao contexto, assinale V para as afirmativas verdadeiras e F para as falsas. (\\_\\_) O vocábulo 'cana-de-açúcar' encontra-se corretamente grafado com hífen, pois, embora as locuções substantivas, em regra, não sejam hifenizadas, trata-se de uma exceção. Por sua vez, 'café da manhã' e 'fim de semana' constituem locuções devidamente grafadas sem o emprego de hífen. (\\_\\_) Os vocábulos 'hiper-raivoso' e 'super-rico' estão corretamente grafados com hífen, uma vez que, com esses prefixos, utiliza-se esse sinal quando o elemento seguinte se inicia por 'r'. De igual modo, o hífen é corretamente empregado nos compostos 'supra-auricular' e 'contra-almirante', apesar de regra distinta. (\\_\\_) Os vocábulos 'antissemita', 'contrarregra' e 'semirreta', que, antes do Novo Acordo Ortográfico, eram grafados com hífen, passaram a ser corretamente escritos sem esse sinal. (\\_\\_) Os vocábulos 'girassol', 'mandachuva' e 'paraquedas' estão corretamente grafados sem hífen, por se tratarem de compostos que, em certa medida, perderam a noção de composição, razão pela qual são escritos de forma aglutinada. Assinale a alternativa que apresenta a sequência CORRETA.","opcoes":["F, V, V, V.","F, F, V, V.","V, F, V, V.","V, V, F, F.","V, V, V, V."],"correta":0,"explicacao":"Gabarito: <strong>F, V, V, V.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["hifen","ortografia"]},{"id":2932,"enunciado":"O advérbio “bem”, quando se combina a outros elementos, pode formar palavras compostas que se unem por hífen (bem-amado); pode aglutinar-se em uma única palavra ou pode permanecer separado. A esse respeito, a palavra que NÃO está devidamente hifenizada é","opcoes":["bem-alto.","bem-vindo.","bem-educado.","bem-sucedido.","bem-humorado."],"correta":0,"explicacao":"Gabarito: <strong>bem-alto.</strong>.","banca":"CEFET-MG","ano":2026,"temas_relacionados":["hifen"]},{"id":2934,"enunciado":"Sobre o emprego de hífen presente nas palavras abaixo, pode-se afirmar corretamente que em apenas uma alternativa tal emprego está incorreto. Indique o emprego incorreto:","opcoes":["Matéria-prima","Auto-estrada","Sobre-humano","Maus-tratos"],"correta":1,"explicacao":"Gabarito: <strong>Auto-estrada</strong>.","banca":"Instituto Indec","ano":2026,"temas_relacionados":["hifen"]},{"id":2936,"enunciado":"\"Aluno e professora criam tecido com bagaço da cana-de-açúcar, em Goiás.\" Considerando o uso do hífen no vocábulo 'cana-de-açúcar', bem como sua adequada justificativa e a aplicação desse recurso em outras palavras alheias ao contexto, assinale V para as afirmativas verdadeiras e F para as falsas. (\\_\\_) O vocábulo 'cana-de-açúcar' encontra-se corretamente grafado com hífen, pois, embora as locuções substantivas, em regra, não sejam hifenizadas, trata-se de uma exceção. Por sua vez, 'café da manhã' e 'fim de semana' constituem locuções devidamente grafadas sem o emprego de hífen. (\\_\\_) Os vocábulos 'hiper-raivoso' e 'super-rico' estão corretamente grafados com hífen, uma vez que, com esses prefixos, utiliza-se esse sinal quando o elemento seguinte se inicia por 'r'. De igual modo, o hífen é corretamente empregado nos compostos 'supra-auricular' e 'contra-almirante', apesar de regra distinta. (\\_\\_) Os vocábulos 'antissemita', 'contrarregra' e 'semirreta', que, antes do Novo Acordo Ortográfico, eram grafados com hífen, passaram a ser corretamente escritos sem esse sinal. (\\_\\_) Os vocábulos 'girassol', 'mandachuva' e 'paraquedas' estão corretamente grafados sem hífen, por se tratarem de compostos que, em certa medida, perderam a noção de composição, razão pela qual são escritos de forma aglutinada. Assinale a alternativa que apresenta a sequência CORRETA.","opcoes":["&#x20;F, V, V, V.","V, V, F, F.","&#x20;F, F, V, V.","V, V, V, V.","V, F, V, V."],"correta":0,"explicacao":"Gabarito: <strong>&#x20;F, V, V, V.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["hifen","ortografia"]},{"id":2938,"enunciado":"\"Esta dependência faz da infraestrutura de abastecimento de água uma vulnerabilidade estratégica, que tanto os Estados Unidos quanto o Irã aparentemente desejam explorar.\" Considerando o emprego do hífen em palavras compostas, analise a palavra 'infraestrutura', assim como outros vocábulos fora do contexto apresentado e identifique a alternativa INCORRETA. I. O vocábulo 'infraestrutura' não recebe hífen, pois, segundo as regras, quando o prefixo ou falso prefixo termina em vogal e o segundo elemento começa com uma vogal diferente ou com uma consoante, não ocorre hífen. II. Os vocábulos 'ultrassom' e 'maxirresultado' estão grafados corretamente sem hífen, e as consoantes 's' e 'r' são duplicadas conforme as regras do Novo Acordo Ortográfico. III. As locuções não são hifenizadas. Exemplos corretos incluem: cor de abóbora, dia a dia, mão de obra e cor de vinho, todas grafadas corretamente sem hífen. IV. Não possuem hífen as palavras que perderam a noção de composição, que devem ser grafadas aglutinadamente. São exemplos corretos: mandachuva, paraquedas e parabrisa. Após análise, assinale a alternativa que apresenta apenas as proposições CORRETAS.","opcoes":["I, III e IV, apenas.","I, II, III e IV.","&#x20;II e IV, apenas.","I e III, apenas.","&#x20;I, II, III, apenas."],"correta":4,"explicacao":"Gabarito: <strong>&#x20;I, II, III, apenas.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["hifen","ortografia"]},{"id":2939,"enunciado":"\"Aluno e professora criam tecido com bagaço da cana-de-açúcar, em Goiás.\" Considerando o uso do hífen no vocábulo 'cana-de-açúcar', bem como sua adequada justificativa e a aplicação desse recurso em outras palavras alheias ao contexto, assinale V para as afirmativas verdadeiras e F para as falsas. (\\_\\_) O vocábulo 'cana-de-açúcar' encontra-se corretamente grafado com hífen, pois, embora as locuções substantivas, em regra, não sejam hifenizadas, trata-se de uma exceção. Por sua vez, 'café da manhã' e 'fim de semana' constituem locuções devidamente grafadas sem o emprego de hífen. (\\_\\_) Os vocábulos 'hiper-raivoso' e 'super-rico' estão corretamente grafados com hífen, uma vez que, com esses prefixos, utiliza-se esse sinal quando o elemento seguinte se inicia por 'r'. De igual modo, o hífen é corretamente empregado nos compostos 'supra-auricular' e 'contra-almirante', apesar de regra distinta. (\\_\\_) Os vocábulos 'antissemita', 'contrarregra' e 'semirreta', que, antes do Novo Acordo Ortográfico, eram grafados com hífen, passaram a ser corretamente escritos sem esse sinal. (\\_\\_) Os vocábulos 'girassol', 'mandachuva' e 'paraquedas' estão corretamente grafados sem hífen, por se tratarem de compostos que, em certa medida, perderam a noção de composição, razão pela qual são escritos de forma aglutinada. Assinale a alternativa que apresenta a sequência CORRETA.","opcoes":["F, F, V, V.","F, V, V, V.","V, V, V, V.","V, V, F, F.","&#x20;V, F, V, V."],"correta":1,"explicacao":"Gabarito: <strong>F, V, V, V.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["hifen","ortografia"]},{"id":2944,"enunciado":"\"E correu ao telefone para chamar a radiopatrulha.\" O vocábulo 'radiopatrulha' não possui hífen. Analise o uso ou não do hífen nos vocábulos das alternativas e identifique aquela que apresenta pelo menos um termo grafado de forma INCORRETA.","opcoes":["Cor de vinho e cor-de-rosa.","&#x20;Anglo-saxão e andorinha-do-mar.","Para-brisa e paraquedas.","Conta-gotas e tenente-coronel.","Anti-semita e extraescolar."],"correta":4,"explicacao":"Gabarito: <strong>Anti-semita e extraescolar.</strong>.","banca":"Unesc","ano":2026,"temas_relacionados":["hifen"]},{"id":2947,"enunciado":"Considerando as regras atuais do uso do hífen, especialmente aquelas definidas pelo Acordo Ortográfico da Língua Portuguesa, a grafia da palavra \"recém-nascido\", destacada no texto, está adequada ao padrão culto. Assinale a alternativa que justifica corretamente essa grafia.","opcoes":["O uso do hífen é opcional, já que o Acordo Ortográfico admite as formas com e sem hífen para compostos iniciados por advérbio.","A grafia com hífen está incorreta, pois a nova ortografia eliminou o uso do hífen em palavras compostas por prefixos seguidos de consoante.","&#x20;O hífen é obrigatório porque \"recém\" é um advérbio que, ao unir-se a particípios, forma palavras compostas com sentido único, exigindo ligação por hífen.","A palavra correta deveria ser grafada separadamente — recém nascido — já que os dois termos mantêm autonomia semântica."],"correta":2,"explicacao":"Gabarito: <strong>&#x20;O hífen é obrigatório porque \"recém\" é um advérbio que, ao unir-se a particípios, forma palavras compostas com sentido único, exigindo ligação por hífen.</strong>.","banca":"ACCESS","ano":2025,"temas_relacionados":["hifen","ortografia"]},{"id":2948,"enunciado":"Considerando as regras atuais do uso do hífen, especialmente aquelas definidas pelo Acordo Ortográfico da Língua Portuguesa, a grafia da palavra \"recém-nascido\", destacada no texto, está adequada ao padrão culto. Assinale a alternativa que justifica corretamente essa grafia.","opcoes":["O uso do hífen é opcional, já que o Acordo Ortográfico admite as formas com e sem hífen para compostos iniciados por advérbio.","A palavra correta deveria ser grafada separadamente — recém nascido — já que os dois termos mantêm autonomia semântica.","A grafia com hífen está incorreta, pois a nova ortografia eliminou o uso do hífen em palavras compostas por prefixos seguidos de consoante.","O hífen é obrigatório porque \"recém\" é um advérbio que, ao unir-se a particípios, forma palavras compostas com sentido único, exigindo ligação por hífen."],"correta":3,"explicacao":"Gabarito: <strong>O hífen é obrigatório porque \"recém\" é um advérbio que, ao unir-se a particípios, forma palavras compostas com sentido único, exigindo ligação por hífen.</strong>.","banca":"ACCESS","ano":2025,"temas_relacionados":["hifen","ortografia"]},{"id":2954,"enunciado":"Acerca das estruturas linguísticas e gramaticais do texto, julgue o item a seguir.\nNo texto, a expressão “doença animal”, presente em “Os primeiros esforços dirigidos contra a doença animal foram descritos nas antigas civilizações da Suméria, do Egito e da Grécia, com referências a curandeiros de animais antes da Era Cristã.”, segundo o acordo ortográfico vigente, poderia ser grafada com hífen: doença‑animal.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["hifen","ortografia"]},{"id":2956,"enunciado":"O Novo Acordo Ortográfico, implementado desde 2009 e obrigatório desde 2016, apresenta regras quanto ao uso de hífen. Associe a segunda coluna de acordo com a primeira, relacionando as regras de uso de hífen com os exemplos: Primeira coluna: regras 1.Emprega-se o hífen nas palavras compostas por justaposição que não contêm formas de ligação e cujos elementos, de natureza nominal, adjetival, numeral ou verbal, constituem uma unidade sintagmática e semântica e mantêm acento próprio. 2.Emprega-se o hífen para ligar duas ou mais palavras que ocasionalmente se combinam, formando não propriamente vocábulos, mas encadeamentos vocabulares. 3.Emprega-se o hífen nas palavras compostas que designam espécies botânicas e zoológicas (com ou sem formas de ligação). Segunda coluna: exemplos (\\_\\_)Rio-Niterói; teoria-prática; ensino-aprendizagem. (\\_\\_)bem-me-quer; abóbora-menina; erva-doce; cobra-d´água. (\\_\\_)anos-luz; afro-asiático; segunda-feira; conta-gotas; amor-perfeito. Assinale a alternativa que apresenta a correta associação entre as colunas:","opcoes":["1 − 2 − 3.","3 − 1 − 2.","2 − 1 − 3.","1 − 3 − 2.","2 − 3 − 1."],"correta":4,"explicacao":"Gabarito: <strong>2 − 3 − 1.</strong>.","banca":"FURB","ano":2025,"temas_relacionados":["hifen","ortografia"]},{"id":2958,"enunciado":"Na oração “Dê preferência a palavras comuns e utilizadas no dia a dia”, a substituição da expressão “dia a dia” por “dia‑a‑dia” é gramaticalmente correta, mas altera o sentido da oração.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["hifen"]},{"id":2961,"enunciado":"A palavra “agrícola-ambiental” aparece grafada com hífen pela mesma razão do seguinte vocábulo abaixo:","opcoes":["bem-me-quer;","&#x20;pré-histórico;","inter-relacionamento;","copo-de-leite","político-econômico"],"correta":4,"explicacao":"Gabarito: <strong>político-econômico</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["hifen"]},{"id":2962,"enunciado":"No que se refere à estruturação linguístico‑gramatical do texto, julgue o item seguinte. Conforme o acordo ortográfico vigente, o termo “cana‑de‑açúcar” tanto pode ser grafado com hífen quanto sem hífen, pois se trata de palavra consagrada pelo uso.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["hifen","ortografia"]},{"id":2965,"enunciado":"\"O pavão é um arco-íris de plumas.\" Quanto à justificativa para o emprego do hífen na palavra 'arco-iris', é correto o que se afirma em:","opcoes":["Emprega-se o hífen em topônimos compostos iniciados por substantivos ou forma verbal. São exemplos dessa mesma regra: Passa-Quatro.","&#x20;Não se emprega hífen quando o prefixo termina em vogal e o segundo elemento começa por consoantes diferentes de 'r' ou 's', por isso, como o Novo Acordo Ortográfico, o vocábulo 'arco-iris' não possui mais hífen. A forma correta é : arco-íris.","&#x20;Emprega-se o hífen nos compostos cujos elementos, reduzidos ou não, perderam a sua significação própria. São hifenizados pela mesma regra: marca-passo e mata-mata.","Emprega-se o hífen nos compostos com o primeiro elemento de forma adjetiva, reduzida ou não. São exemplos dessa mesma regra: histórico-geográfico e afro-asiático."],"correta":2,"explicacao":"Gabarito: <strong>&#x20;Emprega-se o hífen nos compostos cujos elementos, reduzidos ou não, perderam a sua significação própria. São hifenizados pela mesma regra: marca-passo e mata-mata.</strong>.","banca":"IGEDUC","ano":2025,"temas_relacionados":["hifen"]},{"id":2966,"enunciado":"\"Já a solitude, por outro lado, é mais um estado temporário e pode trazer um momento bem-vindo de tranquilidade.\" O emprego do hífen na palavra 'bem-vindo' justifica-se porque o prefixo 'bem' exige hífen. Também são exemplos de vocábulos com o prefixo 'bem' que seguem a regra os seguintes, EXCETO:","opcoes":["bem-amado.","bem-vindo.","bem-estar.","bem-feito."],"correta":3,"explicacao":"Gabarito: <strong>bem-feito.</strong>.","banca":"IGEDUC","ano":2025,"temas_relacionados":["hifen"]},{"id":2976,"enunciado":"Desatualizada Assinale a alternativa em que o uso do hífen está correto.","opcoes":["mini-saia","anti-social","contra-reforma","bem-humorado"],"correta":0,"explicacao":"Gabarito: <strong>mini-saia</strong>.","banca":"Ibest","ano":2025,"temas_relacionados":["hifen"]},{"id":2977,"enunciado":"Em relação às ideias e aos aspectos linguísticos do texto anterior, julgue o item seguinte.\nConforme ortografia oficial atual, o termo “alto-mar” (quarto período do terceiro parágrafo) deveria ser grafado sem hífen — altomar.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["hifen","ortografia"]},{"id":2980,"enunciado":"Em relação ao uso do hífen, considere a palavra \"questão-chave\" no trecho \"Recordo-me também de um trabalho acadêmico, onde meu orientador insistiu na formulação correta da questão-chave antes de avançar.\" De acordo com as novas regras do Acordo Ortográfico de 1990, o uso do hífen está correto. Qual das alternativas abaixo contém a utilização do hífen de forma correta?","opcoes":["Anti-semita.","Auto-aprendizagem.","Pan-americano.","Micro-radiografia."],"correta":2,"explicacao":"Gabarito: <strong>Pan-americano.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["hifen","ortografia"]},{"id":2981,"enunciado":"Em \"Essa visão ignora a complexidade do mundo natural, onde conflitos e relações predador-presa são essenciais e deveriam ser estudados, não censurados\", a palavra \"predador-presa\" está grafada corretamente com hífen, assim como a palavra:","opcoes":["pan-africano.","agro-industrial.","eletro-siderurgia.","contra-senha."],"correta":0,"explicacao":"Gabarito: <strong>pan-africano.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["hifen"]},{"id":2983,"enunciado":"Com base no trecho a seguir: \"Nesse país o português é claro e direto, enquanto os mal-entendidos restam ao português-brasileiro\", analise o uso do hífen na palavra \"mal-entendidos\" e assinale a alternativa correta.","opcoes":["O uso do hífen está correto, pois a palavra é formada por um prefixo \"mal-\" e um elemento que se lhes segue uma unidade sintagmática e semântica e começa por vogal.","O uso do hífen está correto, pois a palavra \"mal-entendidos\" é uma palavra composta que segue a regra de união de prefixo com substantivo iniciando com a mesma letra.","O uso do hífen está errado, pois o prefixo \"mal-\" não requer o hífen quando é seguido por um elemento que se lhes segue uma unidade sintagmática e semântica começado por \"e\".","O hífen deveria ser substituído por um espaço, pois o termo \"mal entendidos\" está incorretamente unido."],"correta":0,"explicacao":"Gabarito: <strong>O uso do hífen está correto, pois a palavra é formada por um prefixo \"mal-\" e um elemento que se lhes segue uma unidade sintagmática e semântica e começa por vogal.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["hifen"]},{"id":2986,"enunciado":"No trecho \"Era como se eu usasse um micro-ondas e tivesse mudado para um forno a gás...\", a palavra \"micro-ondas\" está corretamente grafada de acordo com as normas ortográficas. Assinale a alternativa que apresenta a explicação correta sobre a ortografia dessa palavra.","opcoes":["Usa-se hífen nas formações em que o prefixo ou pseudoprefixo \"micro\" termina na mesma vogal com que se inicia o segundo elemento.","A palavra \"micro-ondas\" deve ser grafada sem hífen, pois trata-se de um composto de formação mais recente, dispensando o uso do sinal.","A palavra \"micro-ondas\" deveria ser grafada como \"microondas\", sem o uso de hífen, por ser um termo estrangeiro adaptado.","A palavra \"micro-ondas\" exige o uso do hífen, mas somente quando é usada em expressões científicas e técnicas, como no caso do uso de fornos industriais."],"correta":0,"explicacao":"Gabarito: <strong>Usa-se hífen nas formações em que o prefixo ou pseudoprefixo \"micro\" termina na mesma vogal com que se inicia o segundo elemento.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["hifen","ortografia"]},{"id":2987,"enunciado":"A palavra “bem−estar” (1º parágrafo) é escrita com hífen. Em qual das alternativas abaixo o uso do hífen está INCORRETO?","opcoes":["Mal−criado.","Bem−humorado.","Mal−estar.","Mal−humorado."],"correta":0,"explicacao":"Gabarito: <strong>Mal−criado.</strong>.","banca":"OBJETIVA","ano":2025,"temas_relacionados":["hifen"]},{"id":2988,"enunciado":"A palavra \"cachorro-quente\" está grafada corretamente com hífen, seguindo as regras do Novo Acordo Ortográfico. Nesse sentido, assinale a única alternativa em que o emprego do hífen está INCORRETO.","opcoes":["Para-quedas.","Guarda-chuva.","Roda-gigante.","Beija-flor."],"correta":0,"explicacao":"Gabarito: <strong>Para-quedas.</strong>.","banca":"IDESG","ano":2025,"temas_relacionados":["hifen","ortografia"]},{"id":2989,"enunciado":"A palavra “contramão” passou a ser escrita sem hífen após a reforma ortográfica. Assinale a alternativa em desacordo com a referida reforma:","opcoes":["Contra-argumento.","Contra-ataque.","Contra hegemonia.","Contra-cena."],"correta":3,"explicacao":"Gabarito: <strong>Contra-cena.</strong>.","banca":"AGIRH","ano":2025,"temas_relacionados":["hifen"]},{"id":2990,"enunciado":"\"Prefeitos, em busca de reeleição, frequentemente intensificam contratações para atender às demandas locais.\" De acordo com o Novo Acordo Ortográfico, o vocábulo 'reeleição' não possui hífen, pois o prefixo 're' se aglutina com palavras começadas por 'e'. As afirmativas a seguir apresentam corretamente as regras para o emprego do hífen, acompanhadas de exemplos que ilustram cada regra, EXCETO:","opcoes":["Emprega-se o hífen quando o 1º elemento termina por vogal, r ou b e o 2º elemento se inicia por h: entre-hostil e infra-hepático.","Emprega-se o hífen quando o 1º elemento termina por consoante igual à que inicia o 2º elemento : ad-digital, sub-base.","Não se emprega o hífen nas locuções, sejam elas substantivas, adjetivas, pronominais, adverbiais, prepositivas ou conjuncionais: cão de guarda, cor de vinho e pé de meia.","Emprega-se o hífen para ligar duas ou mais palavras que ocasionalmente se combinam, formando não propriamente vocábulos, mas encadeamento vocabulares: a divisa Liberdade-Igualdade-Fraternidade."],"correta":2,"explicacao":"Gabarito: <strong>Não se emprega o hífen nas locuções, sejam elas substantivas, adjetivas, pronominais, adverbiais, prepositivas ou conjuncionais: cão de guarda, cor de vinho e pé de meia.</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["hifen","ortografia"]},{"id":2992,"enunciado":"Considerando-se o uso ou não do hífen, assinalar a alternativa em que todas as palavras estão grafadas CORRETAMENTE.","opcoes":["Microondas | contra-ataque | auto-observação.","Além-fronteira | antihigiênico | conta-gotas.","Cor-de-rosa | bem-vindo | azul turquesa.","Capim-acú | corre-corre | semi-interno."],"correta":3,"explicacao":"Gabarito: <strong>Capim-acú | corre-corre | semi-interno.</strong>.","banca":"OBJETIVA","ano":2025,"temas_relacionados":["hifen"]},{"id":977636,"enunciado":"No que diz respeito aos aspectos linguísticos e semânticos do texto, julgue o item. \n\n\n\n\n\n\n\nPoderia ser integrado ao texto, como parágrafo final, o seguinte trecho da obra de Petit referida no texto: A leitura é tida como “inútil”, além de ser um prazer solitário: em nossa época, enquanto lê, a pessoa se afasta do grupo, fica distante, distraída, no sentido mais forte da palavra, isolada. Esse tipo de deserção não é bem-vindo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["hifen"]},{"id":986749,"enunciado":"Acerca dos aspectos linguísticos do texto, julgue o item a seguir.\n\n\n\n\nO vocábulo composto “novo‐velho” (linha 33) tem como núcleo a palavra “velho” e deve ser escrito com hífen, uma vez que é empregado para denominar um grupo contemporâneo de idosos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["hifen"]},{"id":2665168,"enunciado":"De acordo com a estrutura linguística do texto e com sua tipologia, julgue o item a seguir.\n\nA palavra “cotidiano” (linha 6) poderia ser substituída, no texto, preservando‑se sua correção gramatical, por dia‑a‑dia.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["hifen"]},{"id":3632473,"enunciado":"No que se refere à estruturação linguístico‑gramatical do texto, julgue o item seguinte. Conforme o acordo ortográfico vigente, o termo “cana‑de‑açúcar” tanto pode ser grafado com hífen quanto sem hífen, pois se trata de palavra consagrada pelo uso.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["hifen","ortografia"]}];
